    _options = {f"{'Main comparison' if r in primary_rows else 'Archive'} · {r['project']} · {r['variant']} · attempt {r['trial']} · {str(r['outcome']).replace('_', ' ')} · {r['id'][:8]}": r["id"] for r in _ordered}
